<?php
session_start();require_once "../config.php";require_once "../includes/functions.php";require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'Pending';if(in_array($status,['Pending','Shipped','Delivered'],true))$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$status,(int)$_POST['order_id']]);}
$orders=$pdo->query("SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll();$pageTitle="Manage Orders";require "../includes/header.php";?>
<h2>Customer Orders</h2><table class="table"><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o): ?><tr><td>#<?= (int)$o['id'] ?></td><td><?= e($o['name']) ?><br><?= e($o['email']) ?></td><td>₹<?= e($o['total']) ?></td><td><?= e($o['status']) ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><select name="status" class="form-select"><?php foreach(['Pending','Shipped','Delivered'] as $st): ?><option <?= $st===$o['status']?'selected':'' ?>><?= $st ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-primary mt-1">Save</button></form></td></tr><?php endforeach; ?></table><?php require "../includes/footer.php"; ?>
